CREATE TABLE IF NOT EXISTS depots (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, coordinates VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS drivers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL, address VARCHAR(255) NOT NULL, coordinates VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS vehicles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, capacity INTEGER NOT NULL, depot BIGINT NOT NULL REFERENCES depots(id), available BOOLEAN NOT NULL DEFAULT TRUE, driver BIGINT UNIQUE REFERENCES drivers(id));
CREATE TABLE IF NOT EXISTS deliveries (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer BIGINT NOT NULL REFERENCES customers(id), quantity INTEGER NOT NULL, notes TEXT, "timestamp" TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS scenarios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS scenario_vehicles (scenario_id BIGINT NOT NULL REFERENCES scenarios(id), vehicle_id BIGINT NOT NULL REFERENCES vehicles(id), PRIMARY KEY(scenario_id,vehicle_id));
CREATE TABLE IF NOT EXISTS scenario_deliveries (scenario_id BIGINT NOT NULL REFERENCES scenarios(id), delivery_id BIGINT NOT NULL REFERENCES deliveries(id), PRIMARY KEY(scenario_id,delivery_id));
